function middleNode(head: ListNode | null): ListNode | null {
  let n = 0;
  for (let p = head; p; p = p.next) n++;
  let mid = head;
  for (let i = 0; i < Math.floor(n / 2); i++) mid = mid!.next;
  return mid;
}

