class Solution:
    def middleNode(self, head: Optional[ListNode]) -> Optional[ListNode]:
        n, p = 0, head
        while p:
            n += 1
            p = p.next
        mid = head
        for _ in range(n // 2):
            mid = mid.next
        return mid

